package uz.mirix.tracelens.internal;
import org.aopalliance.intercept.MethodInterceptor;import org.springframework.aop.framework.ProxyFactory;import org.springframework.beans.BeansException;import org.springframework.beans.factory.config.BeanPostProcessor;import uz.mirix.tracelens.TraceLensProperties;import javax.sql.DataSource;import java.lang.reflect.Modifier;import java.sql.Connection;
public final class TraceLensDataSourceBeanPostProcessor implements BeanPostProcessor {private final TraceLensProperties p;public TraceLensDataSourceBeanPostProcessor(TraceLensProperties p){this.p=p;}public Object postProcessAfterInitialization(Object bean,String beanName)throws BeansException{if(!p.isEnabled()||!p.getSql().isEnabled()||!(bean instanceof DataSource))return bean;if(Modifier.isFinal(bean.getClass().getModifiers()))return bean;ProxyFactory f=new ProxyFactory(bean);f.setProxyTargetClass(true);f.addAdvice((MethodInterceptor)i->{Object result=i.proceed();if("getConnection".equals(i.getMethod().getName())&&result instanceof Connection c)return JdbcProxyFactory.wrapConnection(c,p);return result;});return f.getProxy(bean.getClass().getClassLoader());}}
